def gcd(a, b):
    """Helper function to compute the greatest common divisor of a and b."""
    while b:
        a, b = b, a % b
    return a

def sum_common_divisors(x, y):
    """Find the sum of common divisors of x and y."""
    total_sum = 0
    for i in range(1, min(x, y) + 1):
        if x % i == 0 and y % i == 0:
            total_sum += i
    return total_sum

