def find_solution(a, b, n):
    # Extended Euclidean Algorithm to find gcd(a, b) and the coefficients x and y
    def extended_gcd(x, y):
        if x == 0:
            return y, 0, 1
        gcd, y1, x1 = extended_gcd(y % x, x)
        y, x = y1 - (y // x) * x1, x1
        return gcd, x, y

    gcd, x, y = extended_gcd(abs(a), abs(b))

    # Check if n is a multiple of gcd
    if n % gcd != 0:
        return None  # No solution exists

    # Scale the solution by n / gcd
    x, y = x * (n // gcd), y * (n // gcd)

    # If a was negative, adjust x appropriately
    if a < 0:
        x = -x

    # If b was negative, adjust y appropriately
    if b < 0:
        y = -y

    return (x, y)

